const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const ts = headers['x-lit-timestamp'];
const eventId = headers['x-lit-event-id'];
const signature = headers['x-lit-signature'];
if (!ts || !eventId || !signature) { throw new Error('Missing signing headers'); }
const body = (item.json && item.json.body) !== undefined ? item.json.body : {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
const expected = 'v1=' + mac;
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const matches = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!matches) { throw new Error('Signature verification failed'); }
const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - Number(ts)) > 300) { throw new Error('Signature timestamp outside tolerance'); }
return [{ json: { verified: true, eventId, timestamp: ts, body } }];

const item = $input.first().json;
const payload = (item.body && item.body.payload) ? item.body.payload : (item.body || {});

const domainList = Array.isArray(payload.domains) ? payload.domains : [
  { domain: 'logicintelligencetechnologies.in', daysUntilExpiry: Number(payload.daysUntilExpiry || 45) },
  { domain: 'automation.logicintelligencetechnologies.in', daysUntilExpiry: Number(payload.automationDaysUntilExpiry || 45) }
];

const criticalDomains = [];
const warningDomains = [];
const healthyDomains = [];

for (const d of domainList) {
  const name = String(d.domain || 'unknown').trim();
  const days = Number(d.daysUntilExpiry || 0);
  const issuer = String(d.issuer || 'Let\'s Encrypt');
  const entry = { domain: name, daysUntilExpiry: days, issuer };

  if (days <= 7) {
    criticalDomains.push(entry);
  } else if (days <= 14) {
    warningDomains.push(entry);
  } else {
    healthyDomains.push(entry);
  }
}

const requiresAction = criticalDomains.length > 0 || warningDomains.length > 0;
const severity = criticalDomains.length > 0 ? 'P0_CRITICAL' : (warningDomains.length > 0 ? 'P2_ELEVATED' : 'P4_INFO');

return [{
  json: {
    eventId: item.eventId,
    verified: item.verified,
    audit: {
      requiresAction,
      severity,
      criticalDomains,
      warningDomains,
      healthyDomains,
      totalAudited: domainList.length,
      auditedAt: new Date().toISOString()
    }
  }
}];

const item = $input.first().json;
const audit = item.audit;

const alertCard = {
  title: `🚨 [${audit.severity}] SSL Certificate Expiry Warning (< 14 Days)`,
  criticalCount: audit.criticalDomains.length,
  warningCount: audit.warningDomains.length,
  actionRequired: 'Verify Caddy automated ZeroSSL/Let\'s Encrypt ACME renewal or manually re-issue TLS certificates.',
  impactedDomains: [...audit.criticalDomains, ...audit.warningDomains],
  escalatedTo: 'Vikash Saravanan (Lead System Engineer)',
  referenceRunbook: 'docs/automation/OPERATIONS_RUNBOOK.md'
};

return [{
  json: {
    eventId: item.eventId,
    status: 'ssl_certificate_warning_dispatched',
    detail: {
      audit,
      alertCard,
      alertedAt: new Date().toISOString()
    }
  }
}];

const item = $input.first().json;
const audit = item.audit;

return [{
  json: {
    eventId: item.eventId,
    status: 'ssl_certificates_healthy',
    detail: {
      totalAudited: audit.totalAudited,
      healthyDomains: audit.healthyDomains,
      nextAuditScheduled: new Date(Date.now() + 86400 * 1000).toISOString()
    }
  }
}];

const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const eventId = item.json.eventId;
const ts = String(Math.floor(Date.now() / 1000));
const payload = {
  eventId,
  status: item.json.status || 'processed',
  detail: item.json.detail || {}
};
const rawBody = JSON.stringify(payload);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
return [{ json: { eventId, status: payload.status, rawBody, timestamp: ts, signature: 'v1=' + mac } }];
